 await fs.writeFile(`${evidence}/source-hook.mjs`,hook);
 instance.state.applyEnv();
 const sessionId='bounded-proof-session';const sessionKey='agent:main:bounded-proof';const timestamp='2026-01-01T00:00:00.000Z';
 await importSqliteSessionRowsBatch([{agentId:'main',env:instance.env,sessionId,sessionKey,entry:{sessionId,updatedAt:Date.now()},transcriptMtimeMs:1,readTranscriptEvents(append){
  append({type:'session',version:3,id:sessionId,cwd:instance.state.workspaceDir,timestamp});let parentId:null|string=null;
